//! A recipe layer's `cursor` key (format 38, spec §7.3, §11 CU-32): what the
//! compositor needs to draw a media's recorded cursor in its clip's layer —
//! the media whose cursor file it is, the source tick to read it at, whether
//! the clip plays reversed, and the clip's cursor props — or `null`.
//!
//! The key is `null` unless the clip's source is a `media` or a `still`, its
//! media has `media.cursor`, that cursor is not `in_picture` (the movie's
//! own picture already shows the pointer, CU-35), and the evaluated props
//! show the pointer or ripple its clicks. `at` is `freeze_frame`'s source
//! tick — `in` plus `source_read_by` (round(S) on a ramp, the base rate
//! otherwise), never below 0, in the stream the clip PLAYS, the reversed one
//! when reversed — or a still's own `at`. The core mirrors nothing (D4-6):
//! the app reads a reversed tick through `ReverseMirror`. `smoothing` and
//! `hide_idle` are the clip's BASE values (`with_base_cursor`), and `props`
//! is all eight keys, so it passes whole to `rc_cursor_query`'s `state`
//! (CU-25). A media clip's layer with a shutter (spec §11 CU-114) appends
//! `shutter`, `{from, to, samples}`: the source ticks its shutter's two ends
//! read, computed as `at` is, omitted when they are equal and on a still.

use serde_json::{Map, Value};

use crate::cursor_props::{clamp_cursor, with_base_cursor};
use crate::evaluate::{json, number};
use crate::model::{Clip, CursorClicks, Project, Source, VideoProps};
use crate::motion_blur::MOTION_BLUR_SAMPLES;
use crate::source_window::source_read_by;
use crate::time::Ticks;

impl Project {
    /// The `cursor` key of `clip`'s layer at clip time `clip_t`, given its
    /// evaluated video props (CU-32): `null`, or `{media, at, reversed,
    /// smoothing, hide_idle, props}`, and `shutter` when `ends` (the layer's
    /// shutter ends in clip time, CU-114) read two source ticks.
    pub(crate) fn layer_cursor(
        &self,
        clip: &Clip,
        clip_t: Ticks,
        evaluated: &VideoProps,
        ends: Option<(Ticks, Ticks)>,
    ) -> Value {
        let (media, at, reversed, shutter) = match &clip.source {
            Source::Media {
                media,
                r#in,
                reversed,
            } => {
                let read = |t: Ticks| r#in.saturating_add(source_read_by(clip, t)).max(0);
                let shutter = ends
                    .map(|(from, to)| (read(from), read(to)))
                    .filter(|(from, to)| from != to);
                (*media, read(clip_t), *reversed, shutter)
            }
            Source::Still { media, at } => (*media, *at, false, None),
            _ => return Value::Null,
        };
        let Some(file) = self.media(media).and_then(|m| m.cursor.as_ref()) else {
            return Value::Null;
        };
        if file.in_picture {
            return Value::Null;
        }
        let mut cursor = with_base_cursor(evaluated.clone(), clip.video.as_ref()).cursor;
        // A file's base values are not checked on read; the evaluator's
        // clamp holds the published props to their ranges whatever they are.
        clamp_cursor(&mut cursor);
        let props = cursor.unwrap_or_default();
        if !props.show && props.clicks != CursorClicks::Ripple {
            return Value::Null;
        }
        let mut out = Map::new();
        out.insert("media".to_string(), Value::from(media));
        out.insert("at".to_string(), Value::from(at));
        out.insert("reversed".to_string(), Value::from(reversed));
        out.insert("smoothing".to_string(), number(props.smoothing));
        out.insert("hide_idle".to_string(), json(&props.hide_idle));
        out.insert("props".to_string(), json(&props));
        if let Some((from, to)) = shutter {
            let mut ends = Map::new();
            ends.insert("from".to_string(), Value::from(from));
            ends.insert("to".to_string(), Value::from(to));
            ends.insert("samples".to_string(), Value::from(MOTION_BLUR_SAMPLES));
            out.insert("shutter".to_string(), Value::Object(ends));
        }
        Value::Object(out)
    }
}
//! A recipe layer's `blur` key (format 42, spec §7.3, §11 CU-111, CU-114):
//! the placements a blurred layer is drawn at across its shutter, or `null`.
//!
//! `recipe.rs`'s `layer` asks [`Project::layer_shutter`] for the layer's
//! shutter — `None` when the evaluated `video.motion_blur` is 0 or the layer
//! is drawn sharp (CU-111's list, which `layer` computes) — and hands it to
//! [`Project::layer_blur`] for the key and to `recipe_cursor.rs` for the
//! cursor's `shutter`. Each sample is the layer's own placement
//! (`Project::placement`, so a nested layer follows its nest's fold and
//! `clip_rect`) at a sub-frame time `motion_blur.rs`'s offsets give, clamped
//! into the instance's span so no sample reads outside the clip. A layer
//! whose every sample equals the first does not move across the shutter, and
//! its key is `null`, so a still layer draws exactly as it did.
//!
//! [`sharpen_matted`] runs over the finished list after Text Behind
//! Subject's copies and cut layers are added (`recipe_subject.rs`): a layer
//! with a non-null `matte` is drawn into or cut by a group whose picture is
//! drawn once, so it is drawn sharp, its `blur` null and its cursor's
//! `shutter` removed.

use serde_json::{Map, Value};

use crate::evaluate::{json, number};
use crate::model::{Project, VideoProps};
use crate::motion_blur::shutter_offsets;
use crate::nest::{Frame, Instance};
use crate::time::Ticks;

/// A layer's shutter at one instant, in PROJECT time: its fraction of a
/// canvas frame, its [`crate::motion_blur::MOTION_BLUR_SAMPLES`] sample
//! The cursor's rules on the model (format 38, spec §11 CU-30, CU-39): the
//! range checks `props_check.rs`'s `check_video` runs on `video.cursor`
//! ([`check_cursor`]), the evaluator's clamp `actions_clamp.rs`'s
//! `clamp_video` runs on an action's end ([`clamp_cursor`], which never
//! fails, so the video group always decodes), the media record's check
//! `edit_track.rs`'s `check_media_fields` ends with ([`check_media_cursor`]),
//! and [`with_base_cursor`] — the one statement of "`smoothing` and
//! `hide_idle` are the clip's own", read by the recipe, `split` and
//! `freeze_frame`.

use crate::actions_clamp::bounded;
use crate::model::{
    CursorProps, Media, MediaKind, VideoProps, CURSOR_CLICK_COLOR, CURSOR_CLICK_SIZE_MAX,
    CURSOR_CLICK_SIZE_MIN, CURSOR_HIDE_IDLE_MAX, CURSOR_HIDE_IDLE_MIN, CURSOR_SCALE_MAX,
    CURSOR_SCALE_MIN,
};
use crate::model_color::normalise_color;
use crate::props_check::in_range;

/// `video.cursor`'s ranges, each refused in `in_range`'s sentence under its
/// own key, then the click colour in G-12's grammar (CU-30). No cursor is
/// nothing to check.
pub(crate) fn check_cursor(cursor: &Option<CursorProps>) -> Result<(), String> {
    let Some(cursor) = cursor else {
        return Ok(());
    };
    in_range(
        "video.cursor.scale",
        cursor.scale,
        CURSOR_SCALE_MIN,
        CURSOR_SCALE_MAX,
    )?;
    in_range("video.cursor.smoothing", cursor.smoothing, 0.0, 1.0)?;
    if let Some(hide_idle) = cursor.hide_idle {
        in_range(
            "video.cursor.hide_idle",
            hide_idle,
            CURSOR_HIDE_IDLE_MIN,
            CURSOR_HIDE_IDLE_MAX,
        )?;
    }
    in_range(
        "video.cursor.click_size",
        cursor.click_size,
        CURSOR_CLICK_SIZE_MIN,
        CURSOR_CLICK_SIZE_MAX,
    )?;
    if normalise_color(&cursor.click_color).is_none() {
        return Err(format!(
            "video.cursor.click_color must be a CSS colour (spec §11 G-12), not \"{}\"",
            cursor.click_color
        ));
    }
    Ok(())
}

/// An evaluated cursor brought into its ranges (CU-30): each number clamped,
/// NaN to its default (`hide_idle`'s NaN to none), the click colour
/// normalised and an unreadable one [`CURSOR_CLICK_COLOR`]. Never fails.
pub(crate) fn clamp_cursor(cursor: &mut Option<CursorProps>) {
    let Some(cursor) = cursor.as_mut() else {
        return;
    };
    cursor.scale = bounded(cursor.scale, CURSOR_SCALE_MIN, CURSOR_SCALE_MAX, 1.0);
    cursor.smoothing = bounded(cursor.smoothing, 0.0, 1.0, 0.0);
    cursor.hide_idle = cursor
        .hide_idle
        .filter(|seconds| !seconds.is_nan())
        .map(|seconds| seconds.clamp(CURSOR_HIDE_IDLE_MIN, CURSOR_HIDE_IDLE_MAX));
    cursor.click_size = bounded(
        cursor.click_size,
        CURSOR_CLICK_SIZE_MIN,
        CURSOR_CLICK_SIZE_MAX,
        1.0,
    );
    cursor.click_color =
        normalise_color(&cursor.click_color).unwrap_or_else(|| CURSOR_CLICK_COLOR.to_string());
}

/// A media's `cursor` (CU-39): an empty path refused, and a cursor on
/// anything but a video media with a picture refused naming what it is.
/// The bookmark is stored as given.
pub(crate) fn check_media_cursor(media: &Media) -> Result<(), String> {
    let Some(cursor) = &media.cursor else {
        return Ok(());
    };
    if cursor.path.trim().is_empty() {
        return Err("media cursor path must not be empty".to_string());
    }
    let what = match media.kind {
        MediaKind::Video if media.has_video => return Ok(()),
        MediaKind::Video => "a video media without a picture",
        MediaKind::Audio => "an audio media",
        MediaKind::Image => "an image media",
        MediaKind::Lut => "a LUT media",
    };
    Err(format!(
        "media.cursor needs a video media with a picture, not {what}"
    ))
}

/// `evaluated` with its cursor's `smoothing` and `hide_idle` set to `base`'s
/// — 0 and none when `base` or its cursor is `None` — so neither ever comes
/// from an action's end (CU-30). A `None` evaluated cursor stays `None`.
/// Read by `recipe_cursor.rs`, and by `split`'s second half and
/// `freeze_frame`'s still, so no splitter turns an end's values into a base.
pub(crate) fn with_base_cursor(mut evaluated: VideoProps, base: Option<&VideoProps>) -> VideoProps {
    if let Some(cursor) = evaluated.cursor.as_mut() {
        let base = base.and_then(|video| video.cursor.as_ref());
        cursor.smoothing = base.map_or(0.0, |base| base.smoothing);
        cursor.hide_idle = base.and_then(|base| base.hide_idle);
    }
    evaluated
}
//! `paste_attributes` — Edit ▸ Paste Attributes and Edit ▸ Paste Graphic
